func TestGeneratedStringFormatInvalid(t *testing.T) {
	tests := []generatedFormatCase{
		{
			name:   "invalid_F",
			format: "%F",
			args:   []generatedFormatArg{{kind: "float", floatVal: 1.0}},
			wantOK: false,
			want:   "invalid conversion '%F' to 'format'",
		},
		{
			name:   "invalid_conv_w",
			format: "%w",
			args:   []generatedFormatArg{{kind: "int", intVal: 42}},
			wantOK: false,
			want:   "invalid conversion '%w' to 'format'",
		},
		{
			name:   "invalid_hash_d",
			format: "%#d",
			args:   []generatedFormatArg{{kind: "int", intVal: 42}},
			wantOK: false,
			want:   "invalid conversion specification: '%#d'",
		},
		{
			name:   "invalid_missing_arg",
			format: "%s %d",
			args:   []generatedFormatArg{{kind: "int", intVal: 1}},
			wantOK: false,
			want:   "bad argument #3 to 'string.format' (no value)",
		},
		{
			name:   "invalid_mod_q",
			format: "%1q",
			args:   []generatedFormatArg{{kind: "string", strVal: "x"}},
			wantOK: false,
			want:   "specifier '%q' cannot have modifiers",
		},
		{
			name:   "invalid_plus_u",
			format: "%+u",
			args:   []generatedFormatArg{{kind: "int", intVal: 42}},
			wantOK: false,
			want:   "invalid conversion specification: '%+u'",
		},
		{
			name:   "invalid_prec_100",
			format: "%.100f",
			args:   []generatedFormatArg{{kind: "float", floatVal: 1.5}},
			wantOK: false,
			want:   "invalid conversion specification: '%.100f'",
		},
		{
			name:   "invalid_prec_p",
			format: "%.2p",
			args:   []generatedFormatArg{{kind: "int", intVal: 1}},
			wantOK: false,
			want:   "invalid conversion specification: '%.2p'",
		},
		{
			name:   "invalid_space_o",
			format: "% o",
			args:   []generatedFormatArg{{kind: "int", intVal: 42}},
			wantOK: false,
			want:   "invalid conversion specification: '% o'",
		},
		{
			name:   "invalid_trailing_percent",
			format: "%",
			args:   []generatedFormatArg{{kind: "int", intVal: 1}},
			wantOK: false,
			want:   "invalid conversion '%' to 'format'",
		},
		{
			name:   "invalid_width_100",
			format: "%100d",
			args:   []generatedFormatArg{{kind: "int", intVal: 1}},
			wantOK: false,
			want:   "invalid conversion specification: '%100d'",
		},
		{
			name:   "invalid_zero_s",
			format: "%0s",
			args:   []generatedFormatArg{{kind: "string", strVal: "x"}},
			wantOK: false,
			want:   "invalid conversion specification: '%0s'",
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			ok, got := runGeneratedFormatCase(tc)
			if ok != tc.wantOK || got != tc.want {
				t.Fatalf("format=%q ok=%v got=%q wantOK=%v want=%q", tc.format, ok, got, tc.wantOK, tc.want)
			}
		})
	}
}

func TestGeneratedStringFormatQuote(t *testing.T) {
	tests := []generatedFormatCase{
		{
			name:   "q_bool",
			format: "%q",
			args:   []generatedFormatArg{{kind: "bool", boolVal: true}},
			wantOK: true,
			want:   "true",
		},
		{
			name:   "q_bool",
			format: "%q",
			args:   []generatedFormatArg{{kind: "bool", boolVal: false}},
			wantOK: true,
			want:   "false",
		},
		{
			name:   "q_float",
			format: "%q",
			args:   []generatedFormatArg{{kind: "float", floatVal: 3.141592653589793}},
			wantOK: true,
			want:   "0x1.921fb54442d18p+1",
		},
		{
			name:   "q_float",
			format: "%q",
			args:   []generatedFormatArg{{kind: "float", floatExpr: "+Inf"}},
			wantOK: true,
			want:   "1e9999",
		},
		{
			name:   "q_int",
			format: "%q",
			args:   []generatedFormatArg{{kind: "int", intVal: 0}},
			wantOK: true,
			want:   "0",
		},
		{
			name:   "q_string",
			format: "%q",
			args:   []generatedFormatArg{{kind: "string", strVal: ""}},
			wantOK: true,
			want:   "\"\"",
		},
		{
			name:   "q_string",
			format: "%q",
			args:   []generatedFormatArg{{kind: "string", strVal: "abc"}},
			wantOK: true,
			want:   "\"abc\"",
		},
		{
			name:   "q_string",
			format: "%q",
			args:   []generatedFormatArg{{kind: "string", strVal: "\"\\\x0a"}},
			wantOK: true,
			want:   "\"\\\"\\\\\\\x0a\"",
		},
		{
			name:   "q_string",
			format: "%q",
			args:   []generatedFormatArg{{kind: "string", strVal: "a\x00b"}},
			wantOK: true,
			want:   "\"a\\0b\"",
		},
		{
			name:   "q_string",
			format: "%q",
			args:   []generatedFormatArg{{kind: "string", strVal: "1\x07"}},
			wantOK: true,
			want:   "\"1\\7\"",
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			ok, got := runGeneratedFormatCase(tc)
			if ok != tc.wantOK || got != tc.want {
				t.Fatalf("format=%q ok=%v got=%q wantOK=%v want=%q", tc.format, ok, got, tc.wantOK, tc.want)
			}
		})
	}
}

